 UIButton *b=[UIButton buttonWithType:UIButtonTypeSystem];UIButtonConfiguration *c=UIButtonConfiguration.tintedButtonConfiguration;c.title=title;c.subtitle=detail;c.image=[UIImage systemImageNamed:folder?@"folder":@"doc.text"];c.imagePadding=10;c.baseForegroundColor=UIColor.labelColor;c.baseBackgroundColor=UIColor.tertiarySystemFillColor;c.cornerStyle=UIButtonConfigurationCornerStyleMedium;c.contentInsets=NSDirectionalEdgeInsetsMake(10,10,10,10);c.titleLineBreakMode=NSLineBreakByTruncatingMiddle;c.subtitleLineBreakMode=NSLineBreakByTruncatingMiddle;c.titleTextAttributesTransformer=^NSDictionary *(NSDictionary *a){NSMutableDictionary *v=[a mutableCopy];v[NSFontAttributeName]=[UIFont systemFontOfSize:12 weight:UIFontWeightMedium];return v;};c.subtitleTextAttributesTransformer=^NSDictionary *(NSDictionary *a){NSMutableDictionary *v=[a mutableCopy];v[NSFontAttributeName]=[UIFont systemFontOfSize:10];v[NSForegroundColorAttributeName]=UIColor.secondaryLabelColor;return v;};b.configuration=c;b.contentHorizontalAlignment=UIControlContentHorizontalAlignmentLeading;[b addAction:[UIAction actionWithHandler:^(UIAction *a){if(tap)tap();}] forControlEvents:UIControlEventTouchUpInside];[b.heightAnchor constraintGreaterThanOrEqualToConstant:52].active=YES;return b;
