UIView *TFAISentAttachments(NSDictionary *message,void(^preview)(NSDictionary *)){
 UIStackView *stack=[UIStackView new];stack.axis=UILayoutConstraintAxisVertical;stack.spacing=6;NSArray *files=[message[@"attachments"] isKindOfClass:NSArray.class]?message[@"attachments"]:@[];NSArray *images=[message[@"images"] isKindOfClass:NSArray.class]?message[@"images"]:@[];
 if(images.count){UIStackView *strip=[UIStackView new];strip.spacing=6;for(NSDictionary *image in images){UIButton *b=[UIButton buttonWithType:UIButtonTypeCustom];b.layer.cornerRadius=10;b.clipsToBounds=YES;b.backgroundColor=UIColor.tertiarySystemFillColor;b.accessibilityLabel=@"查看已发送图片";b.imageView.contentMode=UIViewContentModeScaleAspectFill;[b.widthAnchor constraintEqualToConstant:72].active=YES;[b.heightAnchor constraintEqualToConstant:72].active=YES;[b addAction:[UIAction actionWithHandler:^(UIAction *a){if(preview)preview(@{@"kind":@"image",@"data":image[@"data"]?:@""});}] forControlEvents:UIControlEventTouchUpInside];[strip addArrangedSubview:b];dispatch_async(dispatch_get_global_queue(QOS_CLASS_UTILITY,0),^{UIImage *thumb=Thumbnail(image[@"data"]);dispatch_async(dispatch_get_main_queue(),^{[b setImage:thumb forState:UIControlStateNormal];});});}UIView *space=[UIView new];[strip addArrangedSubview:space];[stack addArrangedSubview:strip];}
 NSMutableDictionary *groups=[NSMutableDictionary new];NSMutableArray *ordered=[NSMutableArray new];for(NSDictionary *f in files){if([f[@"kind"] isEqual:@"image"])continue;NSString *path=f[@"path"]?:@"附件";NSString *parent=path.stringByDeletingLastPathComponent;NSString *key=f[@"directoryGrant"]?: (parent.length?parent:path);if(!groups[key]){groups[key]=[NSMutableArray new];[ordered addObject:key];}[groups[key] addObject:f];}
 NSUInteger shown=0;for(NSString *key in ordered){NSArray *group=groups[key];if(shown++>=3)break;BOOL folder=group.count>1;NSDictionary *first=group.firstObject;NSUInteger bytes=0;for(NSDictionary *f in group)bytes+=[(f[@"originalBytes"]?:f[@"bytes"]) unsignedIntegerValue];NSString *title=folder?[NSString stringWithFormat:@"%@ · %lu 个文件",key.lastPathComponent,(unsigned long)group.count]:[first[@"path"] lastPathComponent];NSString *detail=[NSString stringWithFormat:@"%@ · %@",[NSByteCountFormatter stringFromByteCount:bytes countStyle:NSByteCountFormatterCountStyleFile],first[@"classDumpInputID"]?@"IPA 保留本机 · AI 可调用导出":folder?([first[@"delivery"] isEqual:@"onDemand"]?@"清单已发送 · 按需读取":@"已发送所选内容"):key];if(first[@"directoryGrant"])detail=@"目录授权 · 按需读取 · 点击管理";NSDictionary *item=folder?@{@"kind":@"folder",@"path":key,@"files":group}:first;[stack addArrangedSubview:FileRow(title,detail,folder||first[@"directoryGrant"]!=nil,^{if(preview)preview(item);})];}
 if(ordered.count>3)[stack addArrangedSubview:FileRow([NSString stringWithFormat:@"全部附件（%lu）",(unsigned long)files.count],@"查看本次发送的文件清单",YES,^{if(preview)preview(@{@"kind":@"folder",@"path":@"全部附件",@"files":files});})];return stack;
}
@interface TFAISentPreview : UIViewController
@property NSDictionary *item;
@end
@implementation TFAISentPreview
- (void)viewDidLoad{[super viewDidLoad];self.view.backgroundColor=UIColor.systemBackgroundColor;self.title=[self.item[@"path"] lastPathComponent]?:@"已发送附件";
 if(self.item[@"directoryGrant"]){UITextView *text=[[UITextView alloc]initWithFrame:self.view.bounds];text.autoresizingMask=UIViewAutoresizingFlexibleWidth|UIViewAutoresizingFlexibleHeight;text.editable=NO;text.font=[UIFont preferredFontForTextStyle:UIFontTextStyleBody];text.text=@"此会话获准只读访问这个文件夹及子目录。\n\n文件没有被批量上传或复制。AI 可以按需列目录、搜索和读取；只有读取的片段会发送给当前模型服务商。\n\n目录修改不会自动获得批准。点击右上角可撤销授权，后续读取将停止；已经发送的片段仍保留在历史记录中。";[self.view addSubview:text];self.navigationItem.rightBarButtonItem=[[UIBarButtonItem alloc]initWithPrimaryAction:[UIAction actionWithTitle:@"撤销目录授权" image:[UIImage systemImageNamed:@"folder.badge.minus"] identifier:nil handler:^(UIAction *a){UIAlertController *alert=[UIAlertController alertControllerWithTitle:@"撤销目录授权？" message:@"后续工具将停止访问此文件夹，已发送的内容仍在会话记录中。" preferredStyle:UIAlertControllerStyleAlert];[alert addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[alert addAction:[UIAlertAction actionWithTitle:@"撤销" style:UIAlertActionStyleDestructive handler:^(UIAlertAction *a){NSError *error=nil;BOOL ok=TFAIRevokeDirectory(self.item,&error);text.text=ok?@"目录授权已撤销。":error.localizedDescription;}]];[self presentViewController:alert animated:YES completion:nil];}]];return;}if([self.item[@"kind"] isEqual:@"image"]){UIImageView *image=[UIImageView new];image.contentMode=UIViewContentModeScaleAspectFit;image.frame=self.view.bounds;image.autoresizingMask=UIViewAutoresizingFlexibleWidth|UIViewAutoresizingFlexibleHeight;[self.view addSubview:image];NSDictionary *item=self.item;dispatch_async(dispatch_get_global_queue(QOS_CLASS_UTILITY,0),^{NSData *data=[[NSData alloc]initWithBase64EncodedString:item[@"data"]?:@"" options:0];UIImage *im=[UIImage imageWithData:data];dispatch_async(dispatch_get_main_queue(),^{image.image=im;});});return;}
 if([self.item[@"files"] isKindOfClass:NSArray.class]){UIScrollView *scroll=[UIScrollView new];scroll.frame=self.view.bounds;scroll.autoresizingMask=UIViewAutoresizingFlexibleWidth|UIViewAutoresizingFlexibleHeight;[self.view addSubview:scroll];UIStackView *stack=[UIStackView new];stack.axis=UILayoutConstraintAxisVertical;stack.spacing=8;stack.translatesAutoresizingMaskIntoConstraints=NO;[scroll addSubview:stack];[NSLayoutConstraint activateConstraints:@[[stack.leadingAnchor constraintEqualToAnchor:scroll.contentLayoutGuide.leadingAnchor constant:16],[stack.trailingAnchor constraintEqualToAnchor:scroll.contentLayoutGuide.trailingAnchor constant:-16],[stack.topAnchor constraintEqualToAnchor:scroll.contentLayoutGuide.topAnchor constant:12],[stack.bottomAnchor constraintEqualToAnchor:scroll.contentLayoutGuide.bottomAnchor constant:-16],[stack.widthAnchor constraintEqualToAnchor:scroll.frameLayoutGuide.widthAnchor constant:-32]]];for(NSDictionary *f in self.item[@"files"]){[stack addArrangedSubview:FileRow([f[@"path"] lastPathComponent],f[@"path"]?:@"",NO,^{[self.navigationController pushViewController:TFAISentAttachmentPreview(f) animated:YES];})];}return;}
 UITextView *text=[[UITextView alloc]initWithFrame:self.view.bounds];text.autoresizingMask=UIViewAutoresizingFlexibleWidth|UIViewAutoresizingFlexibleHeight;text.editable=NO;text.font=[UIFont monospacedSystemFontOfSize:13 weight:UIFontWeightRegular];text.text=self.item[@"preview"]?:@"此旧记录仅保留文件清单，未保存预览。";if([self.item[@"previewTruncated"] boolValue])text.text=[text.text stringByAppendingString:@"\n\n预览仅显示前4000字符；正文由模型按需分段读取。"];;[self.view addSubview:text];
}
